}", "style": { "fill": "#ffffff", "stroke": "#2a78d6", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": "mono", "font_size": 13.0, "font_weight": null, "italic": null, "text_color": null, "align": "left", "padding": null } }, { "type": "shape", "id": "out", "kind": "rect", "x": 502.0, "y": 212.0, "w": 432.0, "h": 32.0, "text": "What actually runs", "style": { "fill": "#fce6da", "stroke": "#d9541f", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 15.0, "font_weight": 700, "italic": null, "text_color": "#7a2f0f", "align": null, "padding": null } }, { "type": "shape", "id": "out2", "kind": "rect", "x": 502.0, "y": 248.0, "w": 432.0, "h": 128.0, "text": "function greet(u) {
